 "content": "def transform(grid):
    """Reverse the nested rectangular color layers in each nonzero object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            colors = {grid[y][x] for y, x in cells}
            boxes = {}
            for color in colors:
                pts = [(y, x) for y, x in cells if grid[y][x] == color]
                boxes[color] = (min(y for y, x in pts), max(y for y, x in pts),
                                min(x for y, x in pts), max(x for y, x in pts))
            # Nested rectangular layers have strictly decreasing bounding-box area.
            outer_to_inner = sorted(colors, key=lambda color:
                                    -((boxes[color][1] - boxes[color][0] + 1) *
                                      (boxes[color][3] - boxes[color][2] + 1)))
            remap = {color: outer_to_inner[-1-i]
                     for i, color in enumerate(outer_to_inner)}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
